(function(){
  var GAP = 0.042, PAD = 0.088, CH = 0.066, COLS = 3;
var CATS=[["玄幻", "https://www.zzhhwy.com/xuanhuan/"], ["武侠", "https://www.zzhhwy.com/wuxia/"], ["都市", "https://www.zzhhwy.com/dushi/"], ["历史", "https://www.zzhhwy.com/lishi/"], ["网游", "https://www.zzhhwy.com/wangyou/"], ["科幻", "https://www.zzhhwy.com/kehuan/"], ["其他", "https://www.zzhhwy.com/qita/"], ["女生", "https://www.zzhhwy.com/nusheng/"]];
var RANKS=[["总点击", "https://m.zzhhwy.com/paihangbang/allvisit/"], ["月点击", "https://m.zzhhwy.com/paihangbang/monthvisit/"], ["周点击", "https://m.zzhhwy.com/paihangbang/weekvisit/"], ["总推荐", "https://m.zzhhwy.com/paihangbang/allvote/"], ["月推荐", "https://m.zzhhwy.com/paihangbang/monthvote/"], ["周推荐", "https://m.zzhhwy.com/paihangbang/weekvote/"], ["新入库", "https://m.zzhhwy.com/paihangbang/postdate/"], ["总收藏", "https://m.zzhhwy.com/paihangbang/goodnum/"], ["总字数", "https://m.zzhhwy.com/paihangbang/size/"]];
var FULLS=[["总点击", "https://m.zzhhwy.com/full/allvisit/"], ["月点击", "https://m.zzhhwy.com/full/monthvisit/"], ["周点击", "https://m.zzhhwy.com/full/weekvisit/"], ["总推荐", "https://m.zzhhwy.com/full/allvote/"], ["月推荐", "https://m.zzhhwy.com/full/monthvote/"], ["周推荐", "https://m.zzhhwy.com/full/weekvote/"], ["新入库", "https://m.zzhhwy.com/full/postdate/"], ["总收藏", "https://m.zzhhwy.com/full/goodnum/"], ["总字数", "https://m.zzhhwy.com/full/size/"]];
  var kinds = [];
  function W(t){ var w=0,i,c; for(i=0;i<t.length;i++){ c=t.charAt(i);
      if(c===' ') w+=0.32; else if(c==='\u00b7') w+=0.5; else if(c==='\u25cf') w+=0.9;
      else { w += (t.charCodeAt(i)<128) ? 0.65 : 1.0; } } return w; }
  function span(t){ var cell=(1-GAP*(COLS-1))/COLS, fit=(cell-PAD)/CH;
      var s=Math.ceil(W(t)/fit); if(!s||s<1)s=1; if(s>COLS)s=COLS; return s; }
  function basis(t){ var s=span(t); return s/(COLS+1)+(s-1)*GAP; }
  function bar(t){ kinds.push({title:t, url:'', viewName:"'"+t+"'",
      style:{layout_flexBasisPercent:1, layout_flexGrow:1, layout_wrapBefore:true}}); }
  function push(t,u,first){ kinds.push({title:t, url:u,
      style:{layout_flexBasisPercent:basis(t), layout_flexGrow:1, layout_wrapBefore:!!first}}); }
  function pad(used){ var s=COLS-used; if(s>0){ push('\u3000','',false); } }
  function group(list){ var used=0, first=true, i;
      for(i=0;i<list.length;i++){ var s=span(list[i][0]);
          if(used+s>COLS){ pad(used); used=0; first=true; }
          push(list[i][0], list[i][1], first); first=false; used+=s; }
      if(used>0) pad(used); }

  bar('\ud83d\udcd6 \u63a8\u8350');
  group([['\u9996\u9875\u63a8\u4e66', 'https://m.zzhhwy.com/']]);
  bar('\ud83d\udcda \u5206\u7c7b');
  group(CATS);
  bar('\ud83c\udfc6 \u6392\u884c\u699c');
  group(RANKS);
  bar('\ud83d\udcd5 \u5b8c\u672c\u699c');
  group(FULLS);
  return JSON.stringify(kinds);
})()

