(function(){
  var kw = '';
  try { kw = String(key || ''); } catch (e) {}
  var base = 'https://m.zzhhwy.com';
  var enc = encodeURIComponent(kw);
  if (!kw) { return base + '/'; }
  var keys = ['vw','abw','ru','jrt','van','fw','cwl','gpr','uyoo','tz','euu','tsn',
              'eju','um','fp','dvm','jpk','deblkx','ht','azy','sna','wqx','fpp','rup',
              'jwj','bgt','qp','yf','cw','wq','sign'];
  try {
    java.ajax(base + '/');
    var html = String(java.ajax(base + '/user/search.html?q=' + enc));
    var d = {};
    var re = /var\s+([a-zA-Z]+)\s*=\s*"([^"]*)"/g;
    var m;
    while ((m = re.exec(html)) !== null) { d[m[1]] = m[2]; }
    var parts = [];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      if (typeof d[k] === 'undefined') { return base + '/user/search.html?q=' + enc; }
      parts.push(k + '=' + encodeURIComponent(d[k]));
    }
    parts.push('q=' + enc);
    return base + '/api/search,' + JSON.stringify({
      method: 'POST',
      body: parts.join('&'),
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
        'X-Requested-With': 'XMLHttpRequest',
        'Referer': base + '/user/search.html?q=' + enc
      }
    });
  } catch (e) {
    return base + '/user/search.html?q=' + enc;
  }
})()

