(function () {
  var s = String(result || '');
  var m = /<div[^>]*id="articlecon"[^>]*>([\s\S]*?)<\/div>/i.exec(s);
  if (!m) return '';
  var body = m[1];
  body = body.replace(/<br\s*\/?>/gi, '\n');
  body = body.replace(/<\/p>\s*<p[^>]*>/gi, '\n');
  body = body.replace(/<\/?p[^>]*>/gi, '\n');
  body = body.replace(/<[^>]+>/g, '');
  body = body.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&');
  body = body.replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"');
  body = body.replace(/[ \t\u3000]+/g, ' ');
  body = body.replace(/\n{2,}/g, '\n');
  return body.replace(/^\n+|\n+$/g, '').trim();
})()

