  //   ② 搜索成功会下发 Set-Cookie: ss_search_delay=1（Max-Age 120），期间再搜一律被拦
  //      对策：书源已设 enabledCookieJar=false；这里再显式清一次，兜住旧版忽略开关 / 用户手动开启
  try {
    var u = 'https://wap.shoujixs.net/search/';
