    if (typeof cookie !== 'undefined' && cookie) {
      if (cookie.removeCookie) { try { cookie.removeCookie(u); } catch (b) {} }
      if (cookie.remove) { try { cookie.remove(u); } catch (c) {} }
    }
  } catch (e) {}

  var q = String(key == null ? '' : key).replace(/^[\s\u3000]+|[\s\u3000]+$/g, '');
