@js:

var html = String(result || '');
var g = function (re) {
  var m = html.match(re);
  return m ? m[1] : '';
};

var apiUrl  = g(/["']url["']\s*:\s*["']([^"']+)["']/);
var novel   = g(/["']novel["']\s*:\s*["']([^"']+)["']/);
var chapter = g(/["']chapter["']\s*:\s*["']([^"']+)["']/);
var t       = g(/["']t["']\s*:\s*["']?(\d+)["']?/);
var n       = g(/["']n["']\s*:\s*["']([^"']+)["']/);
var sign    = g(/["']sign["']\s*:\s*["']([^"']+)["']/);


if (!apiUrl || !sign) {
  '取参失败:'
  + '\n apiUrl=' + apiUrl
  + '\n novel='  + novel
  + '\n chapter=' + chapter
  + '\n t='      + t
  + '\n n='      + n
  + '\n sign='   + sign
  + '\n htmlLen=' + html.length;
} else {


  var body = 'url=' + encodeURIComponent(apiUrl)
           + '&mobile=1'
           + '&isk=1'
           + '&novel=' + novel
           + '&chapter=' + chapter
           + '&t=' + t
           + '&n=' + n
           + '&sign=' + sign;


  var ajaxUrl = 'https://ik8.net/conapi.php, ' + JSON.stringify({
    method: 'POST',
    body: String(body),
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
      'X-Requested-With': 'XMLHttpRequest',
      'Referer': String(baseUrl)
    }
  });


  var res = java.ajax(ajaxUrl);


  var resStr = (res && typeof res.body === 'function') ? String(res.body()) : String(res);


  var out;
  try {
    var j = JSON.parse(resStr);
    if (String(j.success) === '1') {
      out = String(j.content || '');
    } else {
      out = '接口异常(success!="1"): ' + resStr.slice(0, 300);
    }
  } catch (e) {
    out = 'JSON 解析失败: ' + resStr.slice(0, 300);
  }
  out;
}

