(function(){
  var raw = String(result);
  var content = raw.match(/(<div[^>]*id="txt"[^>]*>[\s\S]*?<\/div>)/);
  if (content) {
    var text = content[0].replace(/<[^>]+>/g, '').replace(/\s+/g, '');
    if (text.length < 50) {
      var url = baseUrl;
      if (url.indexOf('http') !== 0) {
        url = bhost() + '/' + url.replace(/^\//, '');
      }
      try {
        var webViewContent = String(java.webView(null, url, 'document.getElementById("txt").innerHTML'));
        if (webViewContent && webViewContent.length > 50) {
          return webViewContent;
        }
      } catch(e) {}
    }
    return content[0];
  }
  return raw;
})()

