@js:
(function(){
    try {
        // 1. 获取原标题
        var t = java.getString('a.stui-vodlist__thumb@title', result);
        if (!t) return '';

        // 2. 必须包含 "-"
        if (t.indexOf('-') === -1) return '';

        // 3. 以 "-" 分割，取最后一部分
        var parts = t.split('-');
        var author = parts[parts.length - 1].trim();

        // 4. 过滤：如果截取后的长度小于等于2，或者本身为空，返回空
        if (author.length <= 2) return '';

        // 5. 过滤：如果截取到的是纯数字，返回空（正则 /^\d+$/ 判断是否全为数字）
        if (/^\d+$/.test(author)) return '';

        // 6. 排除常见的非人名后缀
        var invalidWords = ['FHD', 'HD', '4K', '中文字幕', '无码', '有码', '中字'];
        if (invalidWords.indexOf(author) !== -1) return '';

        return author;
    } catch(e) {
        return '';
    }
})()

