ruleContent.content:
@js:(function () {
    var html = String(result || '');
    var base = String(baseUrl || '');

    function get(k) {
        var m = html.match(new RegExp(k + "\\s*=\\s*['\"]([^'\"]+)['\"]"));
        return m ? m[1] : '';
    }
    var AID = get('AID');
    var ASID = get('ASID');
    var ANID = get('ANID');
    var AK = get('AK');

    if (!AID || !AK) return '';

    var origin = '';
    var om = base.match(/^(https?:\/\/[^\/]+)/i);
    if (om) origin = om[1];

    var body = 'id=' + encodeURIComponent(AID)
        + '&sid=' + encodeURIComponent(ASID)
        + '&nid=' + encodeURIComponent(ANID)
        + '&tk=' + encodeURIComponent(AK)
        + '&g=1'
        + '&x=' + Math.floor(Math.random() * 400 + 100)
        + '&y=' + Math.floor(Math.random() * 400 + 100)
        + '&dt=' + Math.floor(Math.random() * 5000 + 3000)
        + '&sw=1080&sh=1920&tz=0'
        + '&t=' + Date.now();

    var postUrl = origin + '/static/count.php,' + JSON.stringify({
        method: 'POST',
        body: body,
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest',
            'Referer': base
        }
    });

    var resp = '';
    try { resp = String(java.ajax(postUrl) || ''); } catch (e) { return ''; }
    if (!resp) return '';

    var json;
    try { json = JSON.parse(resp); } catch (e) { return ''; }
    if (!json || !json.ok || !json.u) return '';

    var videoUrl = '';
    try { videoUrl = String(java.base64Decode(json.u) || ''); } catch (e) { return ''; }
    if (!videoUrl) return '';

    if (videoUrl.indexOf('//') === 0) {
        videoUrl = 'https:' + videoUrl;
    } else if (videoUrl.indexOf('/') === 0) {
        videoUrl = origin + videoUrl;
    }

    return videoUrl;
})()

