@js:
(function () {
    // 1. 提取原始直链
    var m = result.match(/ "contentUrl":\s+"([^"]+)"/);
    if (!m) return '未找到视频源';
    var videoUrl = m[1].replace(/\\\//g, '/');

    // 2. 如果不是 cdn2020 的 t 节点结构，直接返回
    var um = videoUrl.match(/^(https?:\/\/)t(\d+)\.(.+)$/);
    if (!um) return videoUrl;

    // 3. 准备候选节点（缓存优先 -> 原URL -> 近邻）
    var candidates = [];
    var scheme = um[1], curNum = parseInt(um[2], 10), rest = um[3];

    // 缓存优先
    try {
        var lastGoodT = source.get('lastGoodT');
        if (lastGoodT && parseInt(lastGoodT, 10) !== curNum) {
            candidates.push(scheme + 't' + lastGoodT + '.' + rest);
        }
    } catch (e) {}

    candidates.push(videoUrl); // 原 URL

    // 近邻 ±1 ~ ±20 交替
    for (var d = 1; d <= 20; d++) {
        if (curNum - d >= 1) candidates.push(scheme + 't' + (curNum - d) + '.' + rest);
        candidates.push(scheme + 't' + (curNum + d) + '.' + rest);
    }

    // 4. 串行探测（带 8 秒总预算防卡死）
    var START_TS = Date.now();
    var TOTAL_BUDGET = 8000;

    for (var i = 0; i < candidates.length; i++) {
        if (Date.now() - START_TS > TOTAL_BUDGET) break;

        var tryUrl = candidates[i];
        try {
            // 探测请求，超时 1.5 秒
            var txt = String(java.ajax(tryUrl + ',{"timeout":1500,"headers":{"User-Agent":"Mozilla/5.0"}}') || '');
            if (txt.indexOf('#EXTM3U') === 0) {
                // 探测成功，记住这个好节点
                try {
                    var wm = tryUrl.match(/t(\d+)\./);
                    if (wm) source.put('lastGoodT', wm[1]);
                } catch (e) {}
                return tryUrl; // 直接返回可用的纯直链
            }
        } catch (e) {
            // 超时或报错，继续试下一个
        }
    }

    // 5. 如果全挂了，返回原 URL 兜底
    return videoUrl;
})()

